"""analytics: bookkeeping helpers for the analytics area of the ledger service."""
from dataclasses import dataclass, field
from typing import Dict, List

ANALYTICS_LIMIT = 24


@dataclass
class AnalyticsRecord:
    id: int
    label: str
    tags: List[str] = field(default_factory=list)
    attrs: Dict[str, str] = field(default_factory=dict)

    def describe(self):
        return "%s#%d(%s)" % ("analytics", self.id, self.label)


def dedupe_analytics(records):
    """Drop records with a repeated (label, tags) key, keeping the first."""
    seen, out = set(), []
    for r in records:
        key = (r.label.lower(), tuple(sorted(r.tags)))
        if key in seen:
            continue
        seen.add(key)
        out.append(r)
    return out


def group_analytics_by_tag(records):
    """Group AnalyticsRecord objects by each of their tags."""
    out = {}
    for r in records:
        for t in r.tags or ["untagged"]:
            out.setdefault(t, []).append(r)
    for t in out:
        out[t].sort(key=lambda r: (r.label.lower(), r.id))
    return out


def parse_analytics_line(line):
    """Parse 'id|label|tag,tag|k=v;k=v' into a AnalyticsRecord."""
    parts = line.rstrip("\n").split("|")
    if len(parts) != 4:
        raise ValueError("bad line: %r" % line)
    rid, label, tags, attrs = parts
    kv = {}
    for chunk in filter(None, attrs.split(";")):
        k, _, v = chunk.partition("=")
        kv[k.strip()] = v.strip()
    return AnalyticsRecord(int(rid), label.strip(), [t for t in tags.split(",") if t], kv)


def summarize_analytics(records):
    """Small text summary used by the nightly report."""
    if not records:
        return "analytics: no records"
    tags = sorted({t for r in records for t in r.tags})
    longest = max(records, key=lambda r: len(r.label))
    return "analytics: %d records, %d tags, longest label %r" % (len(records), len(tags), longest.label)


def validate_analytics(rec):
    """Return a list of problems found in a AnalyticsRecord."""
    problems = []
    if rec.id <= 0:
        problems.append("id must be positive")
    if not rec.label.strip():
        problems.append("label is empty")
    if len(rec.label) > 24:
        problems.append("label longer than 24")
    for t in rec.tags:
        if " " in t:
            problems.append("tag contains space: " + t)
    return problems


def backoff_analytics(attempt, base=24, cap=3600):
    """Exponential backoff in seconds for the analytics sync job."""
    if attempt < 0:
        raise ValueError("attempt must be >= 0")
    return min(cap, base * (2 ** attempt))


def window_analytics(records, size=3):
    """Yield consecutive windows of AnalyticsRecord objects."""
    buf = []
    for r in records:
        buf.append(r)
        if len(buf) == size:
            yield list(buf)
            buf.pop(0)

