"""Invoice totals."""
from .money import to_cents, from_cents
from .tax import tax_cents


def line_cents(unit_price, qty):
    return to_cents(unit_price) * int(qty)


def invoice_total(lines, tax_rate):
    """lines: list of (unit_price, qty). Returns (subtotal, tax, total) in cents."""
    subtotal = sum(line_cents(p, q) for p, q in lines)
    tax = tax_cents(subtotal, tax_rate)
    return subtotal, tax, subtotal + tax


def invoice_text(lines, tax_rate):
    s, t, g = invoice_total(lines, tax_rate)
    return "subtotal %s tax %s total %s" % (from_cents(s), from_cents(t), from_cents(g))

