files.ledger/money.py:
"""Money helpers. All amounts inside the ledger are integer cents."""


def to_cents(amount):
    """Convert a decimal amount (float/str/int, in dollars) to integer cents.

    Fractions of a cent are rounded half-up (0.285 dollars -> 29 cents).
    """
    return int(float(amount) * 100)


def from_cents(cents):
    return "%d.%02d" % divmod(int(cents), 100)


def split_evenly(cents, parts):
    base, extra = divmod(int(cents), parts)
    return [base + (1 if i < extra else 0) for i in range(parts)]

