def dedupe_shipping(records):
    """Drop records with a repeated (label, tags) key, keeping the first."""
    seen, out = set(), []
    for r in records:
        key = (r.label.lower(), tuple(sorted(r.tags)))
        if key in seen:
            continue
        seen.add(key)
        out.append(r)
    return out


def render_shipping_table(records, width=32):
    """Plain-text table, labels clipped to width."""
    rows = ["%-6s %-32s %s" % ("ID", "LABEL", "TAGS")]
    for r in records:
        label = r.label if len(r.label) <= width else r.label[:width - 1] + "~"
        rows.append("%-6d %-32s %s" % (r.id, label, ",".join(r.tags)))
    return "\n".join(rows)


def validate_shipping(rec):
    """Return a list of problems found in a ShippingRecord."""
    problems = []
    if rec.id <= 0:
        problems.append("id must be positive")
    if not rec.label.strip():
        problems.append("label is empty")
    if len(rec.label) > 32:
        problems.append("label longer than 32")
    for t in rec.tags:
        if " " in t:
            problems.append("tag contains space: " + t)
    return problems


def window_shipping(records, size=2):
    """Yield consecutive windows of ShippingRecord objects."""
    buf = []
    for r in records:
        buf.append(r)
        if len(buf) == size:
            yield list(buf)
            buf.pop(0)


def summarize_shipping(records):
    """Small text summary used by the nightly report."""
    if not records:
        return "shipping: no records"
    tags = sorted({t for r in records for t in r.tags})
    longest = max(records, key=lambda r: len(r.label))
    return "shipping: %d records, %d tags, longest label %r" % (len(records), len(tags), longest.label)


def backoff_shipping(attempt, base=32, cap=3600):
    """Exponential backoff in seconds for the shipping sync job."""
    if attempt < 0:
        raise ValueError("attempt must be >= 0")
    return min(cap, base * (2 ** attempt))


def group_shipping_by_tag(records):
    """Group ShippingRecord objects by each of their tags."""
    out = {}
    for r in records:
        for t in r.tags or ["untagged"]:
            out.setdefault(t, []).append(r)
    for t in out:
        out[t].sort(key=lambda r: (r.label.lower(), r.id))
    return out

