"""suppliers: bookkeeping helpers for the suppliers area of the ledger service."""
from dataclasses import dataclass, field
from typing import Dict, List

SUPPLIERS_LIMIT = 32


@dataclass
class SuppliersRecord:
    id: int
    label: str
    tags: List[str] = field(default_factory=list)
    attrs: Dict[str, str] = field(default_factory=dict)

    def describe(self):
        return "%s#%d(%s)" % ("suppliers", self.id, self.label)


def window_suppliers(records, size=2):
    """Yield consecutive windows of SuppliersRecord objects."""
    buf = []
    for r in records:
        buf.append(r)
        if len(buf) == size:
            yield list(buf)
            buf.pop(0)


def summarize_suppliers(records):
    """Small text summary used by the nightly report."""
    if not records:
        return "suppliers: no records"
    tags = sorted({t for r in records for t in r.tags})
    longest = max(records, key=lambda r: len(r.label))
    return "suppliers: %d records, %d tags, longest label %r" % (len(records), len(tags), longest.label)


def backoff_suppliers(attempt, base=32, cap=3600):
    """Exponential backoff in seconds for the suppliers sync job."""
    if attempt < 0:
        raise ValueError("attempt must be >= 0")
    return min(cap, base * (2 ** attempt))


def paginate_suppliers(records, page, size=32):
    """Return (items, total_pages) for 1-based page numbers."""
    if size <= 0:
        raise ValueError("size must be positive")
    total_pages = max(1, -(-len(records) // size))
    page = min(max(page, 1), total_pages)
    start = (page - 1) * size
    return records[start:start + size], total_pages


def parse_suppliers_line(line):
    """Parse 'id|label|tag,tag|k=v;k=v' into a SuppliersRecord."""
    parts = line.rstrip("\n").split("|")
    if len(parts) != 4:
        raise ValueError("bad line: %r" % line)
    rid, label, tags, attrs = parts
    kv = {}
    for chunk in filter(None, attrs.split(";")):
        k, _, v = chunk.partition("=")
        kv[k.strip()] = v.strip()
    return SuppliersRecord(int(rid), label.strip(), [t for t in tags.split(",") if t], kv)


def merge_suppliers(a, b):
    """Merge two SuppliersRecord objects; b wins on attrs, tags are united in order."""
    tags = list(a.tags)
    for t in b.tags:
        if t not in tags:
            tags.append(t)
    attrs = dict(a.attrs)
    attrs.update(b.attrs)
    return SuppliersRecord(a.id, b.label or a.label, tags, attrs)


def render_suppliers_table(records, width=32):
    """Plain-text table, labels clipped to width."""
    rows = ["%-6s %-32s %s" % ("ID", "LABEL", "TAGS")]
    for r in records:
