        rows.append("%-6d %-32s %s" % (r.id, label, ",".join(r.tags)))
    return "\n".join(rows)


def validate_suppliers(rec):
    """Return a list of problems found in a SuppliersRecord."""
    problems = []
    if rec.id <= 0:
        problems.append("id must be positive")
    if not rec.label.strip():
        problems.append("label is empty")
    if len(rec.label) > 32:
        problems.append("label longer than 32")
    for t in rec.tags:
        if " " in t:
            problems.append("tag contains space: " + t)
